BEGIN;
CREATE TABLE IF NOT EXISTS whatsapp_order_draft(id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,conversation_id integer NOT NULL REFERENCES whatsapp_conversation(id) ON DELETE CASCADE,customer_id integer NULL REFERENCES customer(id) ON DELETE SET NULL,branch_id integer NOT NULL REFERENCES branch(id) ON DELETE RESTRICT,order_type varchar(30) NULL,address_id integer NULL REFERENCES address(id) ON DELETE SET NULL,status varchar(40) NOT NULL DEFAULT 'Building',payment_method varchar(30) NULL,payment_method_id integer NULL,cash_received integer NULL,change_amount integer NULL,subtotal integer NOT NULL DEFAULT 0,delivery_fee integer NOT NULL DEFAULT 0,discount_total integer NOT NULL DEFAULT 0,total integer NOT NULL DEFAULT 0,notes varchar(1000) NULL,confirmed_at timestamptz NULL,cancelled_at timestamptz NULL,cancelled_reason varchar(500) NULL,order_id integer NULL REFERENCES "order"(id) ON DELETE SET NULL,version bigint NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT NOW(),updated_at timestamptz NOT NULL DEFAULT NOW(),CONSTRAINT ck_whatsapp_order_draft_totals CHECK(subtotal>=0 AND delivery_fee>=0 AND discount_total>=0 AND total>=0),CONSTRAINT ck_whatsapp_order_draft_cash CHECK(cash_received IS NULL OR cash_received>=0),CONSTRAINT ck_whatsapp_order_draft_status CHECK(status IN('Building','AwaitingCustomerData','AwaitingAddress','AwaitingPayment','ReadyForConfirmation','Confirmed','Cancelled','Expired','ConvertedToOrder')));
CREATE TABLE IF NOT EXISTS whatsapp_order_draft_item(id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,draft_id integer NOT NULL REFERENCES whatsapp_order_draft(id) ON DELETE CASCADE,product_id integer NOT NULL REFERENCES product(id) ON DELETE RESTRICT,quantity integer NOT NULL,unit_price integer NOT NULL,notes varchar(500) NULL,selected_options jsonb NULL,subtotal integer NOT NULL,created_at timestamptz NOT NULL DEFAULT NOW(),updated_at timestamptz NOT NULL DEFAULT NOW(),CONSTRAINT ck_whatsapp_order_draft_item_values CHECK(quantity>0 AND unit_price>=0 AND subtotal>=0));
CREATE TABLE IF NOT EXISTS whatsapp_order_confirmation(id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,draft_id integer NOT NULL REFERENCES whatsapp_order_draft(id) ON DELETE CASCADE,confirmation_message_id integer NOT NULL REFERENCES whatsapp_message(id) ON DELETE RESTRICT,order_id integer NULL REFERENCES "order"(id) ON DELETE SET NULL,confirmed_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT NOW(),updated_at timestamptz NOT NULL DEFAULT NOW());
CREATE UNIQUE INDEX IF NOT EXISTS ux_whatsapp_order_draft_active_conversation ON whatsapp_order_draft(conversation_id) WHERE status IN('Building','AwaitingCustomerData','AwaitingAddress','AwaitingPayment','ReadyForConfirmation');
CREATE INDEX IF NOT EXISTS ix_whatsapp_order_draft_customer ON whatsapp_order_draft(customer_id);
CREATE INDEX IF NOT EXISTS ix_whatsapp_order_draft_branch ON whatsapp_order_draft(branch_id);
CREATE INDEX IF NOT EXISTS ix_whatsapp_order_draft_item_draft ON whatsapp_order_draft_item(draft_id);
CREATE INDEX IF NOT EXISTS ix_whatsapp_order_draft_item_product ON whatsapp_order_draft_item(product_id);
CREATE UNIQUE INDEX IF NOT EXISTS ux_whatsapp_order_confirmation_message ON whatsapp_order_confirmation(draft_id,confirmation_message_id);
COMMIT;
